    score -= early_factor * post_residual as f64;

    // Penalize deviation from the mean residual, but only for positive gaps
    let pos_gap = (post_residual as f64 - mean_residual).max(0.0);
    score -= 2.0 * pos_gap.powf(1.1);

    // Reward bins that are relatively full
