    // Special case: next item fits in a new bin but not the current one
    if next_item_size > 0
        && next_item_size <= bin_capacity
        && next_item_size > post_residual
        && bin_residual == bin_capacity
    {
        score -= 3.5;
    }

    // Minor tweak: penalise a large residual when it’s the only fitting bin
    if fitting_bins_count == 1 && (post_residual as f64 - mean_residual).abs() > 10.0 {
