    // Mean gap penalty
    let mean_gap = (post_residual as f64 - mean_residual).max(0.0);
    score -= 4.0 * mean_gap.powf(1.4);

    // Dead‑space penalty weighted by progress
    score -= 3.0 * dead_space_ratio.powi(2) * (1.0 + progress * 0.5);

    // Early‑stream bonus
    let early_weight = reverse_progress.powf(2.5);
    score -= early_weight * dead_space_ratio.powi(3);

    // Open‑bins penalty (log‑squared)
    score += 0.5 * ((open_bins_count as f64 + 1.0).ln()).powi(2);

    // Rarity bonus
    let rarity_factor = 1.0 / ((fitting_bins_count as f64 + 1.0).ln() + 1.0);
    score -= 4.0 * rarity_factor;

    // Look‑ahead for next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let after_next = post_residual - next_item_size;
            score -= 2.5 * after_next as f64;
        } else {
            let slack = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 3.0 * slack.powi(3);
        }
    }

    // Current item does not fit
    if bin_residual > 0 && bin_residual < item_size {
        let slack = (item_size - bin_residual) as f64 / bin_capacity as f64;
        score += 6.0 * slack.powi(3);
    }

    // New‑bin handling
    if bin_residual == bin_capacity {
        if open_bins_count > 5 && mean_residual > 0.15 * bin_capacity as f64 {
            score += 2.0 * progress.powf(0.7);
        } else {
            score -= 4.0 * progress.powf(1.2);
        }
    }

    // Extreme fill ratios
    if fill_ratio < 0.05 {
        score += 2.0;
    } else if fill_ratio > 0.98 {
        score -= 1.5;
    }

    // Reward residual close to item size
    let item_ratio = item_size as f64 / bin_capacity as f64;
    let diff = (residual_ratio - item_ratio).abs();
    if diff < 0.03 {
        score -= 0.8 * (0.03 - diff);
    }

    // Residual deviation penalty
    let residual_deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.4 * (residual_deviation / bin_capacity as f64).powi(2);

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
