    // 2. Open‑bin pressure (sub‑linear)
    let open_pen = (open_bins_count as f64 + 1.0).ln() * 0.25;
    score += open_pen;

    // 3. Residual vs mean: reward closeness, penalise deviation
    let diff = (post_residual as f64 - mean_residual).abs();
    if diff < mean_residual * 0.15 {
        score -= 4.0 * diff; // close to mean is good
    } else {
        score += 0.3 * diff; // far from mean is bad
    }

    // 4. Fitting‑bin count penalty (quadratic for many options)
    if fitting_bins_count > 2 {
        score += 0.02 * ((fitting_bins_count as f64 - 2.0).powi(2));
    }

    // 5. New‑bin candidate penalty
    if bin_residual == bin_capacity {
        let new_pen = 3.5 * (open_bins_count as f64).min(6.0)
            + mean_residual * 0.20;
        score += new_pen;
    }

    // 6. Late‑phase bias: favour existing bins near the end
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.92 {
            score += 180.0 * (1.0 - progress) / 0.08;
        } else if progress > 0.78 {
            score += 90.0 * (1.0 - progress) / 0.22;
        }
    }

    // 7. Fit ratio reward / penalty
    if bin_residual > 0 {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio >= 0.98 {
            score -= 12.0;
        } else if fit_ratio <= 0.35 {
            score += 5.0;
        }
    }

    // 8. Lookahead coupling: anticipate the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits into the same bin
            score -= 7.0;
        } else {
            // Next item would spill into a new bin
            let future_ratio = next_item_size as f64 / bin_capacity as f64;
            score -= 0.20 * future_ratio * (bin_capacity as f64 - post_residual as f64);
        }
    }

    // 9. Residual ratio penalty for excessive waste
    let dead_ratio = if bin_capacity > 0 {
        (bin_capacity - post_residual) as f64 / bin_capacity as f64
    } else {
        1.0
    };
    if dead_ratio > 0.55 {
        score += 8.0 * (dead_ratio - 0.55);
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // ----- base score: weighted residual -----
    let base_residual = post_residual as f64;
    let residual_ratio = base_residual / bin_capacity as f64;
    let mut score = base_residual * (1.0 + 0.6 * residual_ratio);

    // ----- dynamic lookahead penalty -----
    if next_item_size > 0 && base_residual < next_item_size as f64 {
        let time_factor = 1.0 - (step_index as f64 / total_items as f64);
        let ratio = (next_item_size as f64 - base_residual) / next_item_size as f64;
        let penalty = 200.0 * ratio * (time_factor + 0.3).max(0.3);
        score += penalty;
    }

    // ----- open‑bin pressure with adaptive scaling -----
    let open_weight = 0.25 * (1.0 - (step_index as f64 / total_items as f64)).max(0.1);
    score += (open_bins_count as f64) * open_weight;
    if open_bins_count > 10 {
        score += 5.0;
    }

    // ----- residual vs mean comparison with quadratic tuning -----
    let diff = base_residual - mean_residual;
    if diff > 0.0 {
        score += diff.powi(2) * 0.03;
    } else {
        score -= (-diff).powi(2) * 0.02;
    }

    // ----- last‑chance penalty -----
    if fitting_bins_count == 1 && base_residual > 0.0 {
        score += 40.0;
    }

    // ----- new‑bin candidate adjustment -----
    if bin_residual == bin_capacity {
        let ratio = item_size as f64 / bin_capacity as f64;
        let mut new_score = 0.0;
        if ratio > 0.95 {
            new_score -= 300.0; // very large item
        } else if mean_residual > 20.0 {
            new_score -= 200.0; // tight space
        } else {
            new_score -= 50.0; // moderate reward
        }
        new_score += (open_bins_count as f64) * 0.1;
        if step_index < total_items / 10 {
            new_score -= 30.0; // early stream prefers new bins
        }
        score += new_score;
    }

    // ----- refined lookahead adjustment -----
    if next_item_size > 0 && bin_residual >= next_item_size {
        let next_residual = bin_residual - next_item_size;
        if next_residual < 5 {
            score -= 20.0; // avoid tiny gap
        } else if next_residual < 15 {
            score -= 10.0; // moderate penalty
        } else {
            score += 2.0; // slight encouragement
        }
    }

    // ----- late‑stream residual amplification -----
    if step_index > total_items * 4 / 5 {
        score *= 1.05; // slightly penalize large residuals later
    }

    score
}

pub fn score_bin(
    item_size: u32,
