) -> f64 {
    // ----- basic fit score -----
    // Encourage acceptance of smaller items, but with a gentler penalty
    let mut score = post_residual as f64 - (item_size as f64) * 0.015;

    // ----- residual ratio handling -----
    let residual_ratio = post_residual as f64 / bin_capacity as f64;

    // Tight fits are strongly rewarded
    if residual_ratio <= 0.10 {
        score -= 1.2 * residual_ratio;
    } else if residual_ratio <= 0.30 {
        score -= 0.6 * residual_ratio;
    } else {
        score -= 0.3 * residual_ratio;
    }

    // Penalize moderate slack to drive tighter packing
    if residual_ratio > 0.25 {
        score -= 0.35 * residual_ratio;
    }

    // ----- lookahead with remaining‑item weighting -----
    let remaining_ratio = (total_items - step_index) as f64 / total_items as f64;
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        // More penalty when many items are left
        score -= (slack as f64) * 0.4 * remaining_ratio.max(0.3);
    }

    // ----- penalty for inevitable overflow -----
    if next_item_size > 0 && post_residual < next_item_size {
        let penalty = 600.0 * remaining_ratio.max(0.15);
        score += penalty;
    }

    // ----- open‑bin pressure (diminishing factor) -----
    let open_weight = 0.40 / (1.0 + 0.15 * open_bins_count as f64);
    score += (open_bins_count as f64) * open_weight;

    // ----- mean residual comparison -----
    let residual_diff = post_residual as f64 - mean_residual;
    if residual_diff > 0.0 {
        // wasteful space
        score += residual_diff * 0.90;
    } else {
        // tighter packing
        score += residual_diff * 0.20;
    }

    // ----- single‑fit bonus -----
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 30.0;
    }

    // ----- new‑bin candidate adjustment -----
    if bin_residual == bin_capacity {
        let early_factor = 1.0 - (step_index as f64 / total_items as f64);
        let mut new_bin_score = 0.0;
        // Prefer a new bin when average waste is low
        new_bin_score -= mean_residual * 0.50;
        // Discourage opening when many bins are already open
        new_bin_score += (open_bins_count as f64) * 0.40;
        // Early‑opening reward
        new_bin_score += early_factor * 10.0;
        score += new_bin_score;
    }

    // ----- high‑ratio next‑item penalty -----
    if next_item_size > 0 {
        let ratio = next_item_size as f64 / bin_capacity as f64;
        if ratio > 0.70 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(
    item_size: u32,
