    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Residual and ratio
    let residual = post_residual as f64;
    let ratio = residual / bin_capacity as f64;

    // Base score: weighted residual with a quadratic early‑time factor
    let time_ratio = (step_index as f64) / (total_items as f64).max(1.0);
    let early_weight = 1.0 + 1.2 * (1.0 - time_ratio) * ratio.powi(2);
    let mut score = residual * early_weight;

    // Tight‑fit incentive
    if ratio < 0.04 {
        score -= 22.0;
    } else if ratio < 0.12 {
        score -= 10.0;
    }

    // Look‑ahead adjustment
    if next_item_size > 0 {
        let future_residual = if bin_residual >= next_item_size {
            bin_residual - next_item_size
        } else {
            bin_residual
        };
        let future_ratio = future_residual as f64 / bin_capacity as f64;

        // Penalize bins that become too tight after the next item
        if future_ratio < 0.07 {
            score += 30.0;
        } else if future_ratio < 0.17 {
            score += 12.0;
        } else {
            score -= 5.0;
        }

        // Extra penalty if current residual cannot host next item
        if residual < next_item_size as f64 {
            let diff = (next_item_size as f64 - residual) / next_item_size as f64;
            let time_factor = (time_ratio.powi(3)).max(0.05);
            score += 120.0 * diff * (1.0 - time_factor);
        }
    }

    // Open‑bin pressure: stronger quadratic penalty
    let open_penalty = 0.02 * (open_bins_count as f64).powi(2)
        + 0.15 * (open_bins_count as f64)
        + if open_bins_count > 8 { 4.0 } else { 0.0 };
    score += open_penalty;

    // Residual vs mean comparison: quadratic reward/penalty
    let diff_mean = residual - mean_residual;
    if diff_mean > 0.0 {
        score += diff_mean.powi(2) * 0.018;
    } else {
        score -= (-diff_mean).powi(2) * 0.012;
    }

    // Fitting bins count adjustment: prefer bins with many options
    if fitting_bins_count > 4 {
        score -= 4.0;
    } else if fitting_bins_count == 1 && residual > 0.0 {
        score += 28.0;
    }

    // New‑bin candidate adjustment
    if bin_residual == bin_capacity {
        let ratio_item = item_size as f64 / bin_capacity as f64;
        let mut new_score = 0.0;
        if ratio_item > 0.95 {
            new_score -= 260.0;          // very large item
        } else if mean_residual > 15.0 {
            new_score -= 180.0;          // overall tight space
        } else {
            new_score -= 40.0;           // moderate reward
        }
        new_score += (open_bins_count as f64) * 0.08;
        // Early stream prefers new bins
        if step_index < total_items / 5 {
            new_score -= 22.0;
        }
        // Late stream discourages new bins
        if step_index > total_items * 4 / 5 {
            new_score += 18.0;
        }
        score += new_score;
    }

    // Late‑stream residual amplification
    if step_index > total_items * 4 / 5 {
        score *= 0.96;
    }

    score
}

pub fn score_bin(
